(function(){
const words={
 accessGroups:['共同組別與表單權限設定','Shared groups and form permissions','Grupos y permisos de formularios','Nhóm chung và quyền biểu mẫu'],accessPeople:['帳號組別指派','Assign account groups','Asignar grupos de cuentas','Gán nhóm tài khoản'],accessCount:['組','groups','grupos','nhóm'],accessMembers:['位成員','members','miembros','thành viên'],accessGroupName:['共同組別名稱','Shared group name','Nombre del grupo','Tên nhóm chung'],accessDepartments:['可管理的部門（可複選）','Managed departments (multiple)','Departamentos administrados (varios)','Bộ phận được quản lý (chọn nhiều)'],accessView:['查看','View','Ver','Xem'],accessCreate:['新增','Create','Crear','Thêm'],accessEdit:['編輯','Edit','Editar','Sửa'],accessDelete:['刪除','Delete','Eliminar','Xóa'],accessApprove:['審核／簽核','Review / approve','Revisar / aprobar','Duyệt / ký'],accessForm:['系統表單／功能','Form / function','Formulario / función','Biểu mẫu / chức năng'],accessNewGroup:['新增共同組別','New shared group','Nuevo grupo','Thêm nhóm chung'],accessEnabled:['啟用此組別','Enable group','Activar grupo','Bật nhóm'],accessManaged:['使用共同組別權限','Use shared group permissions','Usar permisos de grupos','Dùng quyền nhóm chung'],accessHelp:['每個國家最多 20 個共同組別。先選擇部門，再設定表單權限；帳號加入多組時，按各組授權的部門合併權限。未提供的操作以「—」顯示；已填寫的點檢紀錄不提供刪除。','Up to 20 groups per country. Select departments, then form permissions. Account grants combine within each group’s departments. Unsupported actions show —; inspection history cannot be deleted.','Hasta 20 grupos por país. Seleccione departamentos y permisos. Se combinan los permisos dentro de los departamentos de cada grupo. — indica operaciones no disponibles; no se elimina el historial.','Tối đa 20 nhóm mỗi quốc gia. Chọn bộ phận rồi đặt quyền. Quyền được gộp trong phạm vi bộ phận của từng nhóm. — là thao tác không hỗ trợ; không xóa lịch sử kiểm tra.'],accessPeopleHelp:['未啟用共同組別時，維持原有單部門權限。啟用後只使用所選組別授權；沒有勾選組別或組別已停用時，不授予表單權限。設定會於下一次載入或操作時生效，伺服器會重新查核。','When disabled, existing single-department access remains. When enabled, only selected groups grant access. No groups or inactive groups grant no access. Changes apply at the next load or request; the server rechecks.','Si se desactiva, se mantiene el acceso original a un departamento. Si se activa, solo se aplican los grupos seleccionados. Sin grupos activos no hay acceso. El servidor verifica en la siguiente carga u operación.','Khi tắt, giữ quyền một bộ phận ban đầu. Khi bật, chỉ dùng quyền nhóm đã chọn. Không có nhóm hoạt động thì không có quyền. Máy chủ kiểm tra lại khi tải hoặc thao tác tiếp.'],accessAccountChoose:['選擇主管／幹部帳號','Select supervisor account','Seleccionar cuenta de supervisor','Chọn tài khoản quản lý'],accessOldAccounts:['帳號新增、密碼與基本資料管理','Accounts, passwords and basic details','Cuentas, contraseñas y datos','Tài khoản, mật khẩu và thông tin'],accessEmpty:['尚未建立共同組別，請新增組別。','No shared groups yet. Create a group.','No hay grupos. Cree uno.','Chưa có nhóm chung. Hãy thêm nhóm.'],accessNoAccounts:['目前國家沒有可指派的主管帳號。請先在帳號管理建立主管帳號。','No supervisor accounts in this country. Create one in account management.','No hay supervisores en este país. Cree una cuenta.','Chưa có tài khoản quản lý tại quốc gia này. Hãy tạo tài khoản.'],accessDenied:['未授權此操作或部門，請聯絡管理員調整權限。','This operation or department is not authorized. Ask an administrator to adjust access.','Esta operación o departamento no está autorizado. Contacte al administrador.','Không có quyền thao tác hoặc bộ phận này. Liên hệ quản trị viên.'],accessNoRights:['此帳號目前沒有此功能的查看權限，請聯絡管理員設定共同組別。','This account has no view permission here. Ask an administrator to configure its groups.','Esta cuenta no tiene permiso de consulta. Solicite al administrador que configure sus grupos.','Tài khoản chưa có quyền xem chức năng này. Nhờ quản trị viên thiết lập nhóm.'],accessUnsaved:['有尚未儲存的權限修改，確定離開？','Leave with unsaved permission changes?','¿Salir sin guardar los permisos?','Rời đi khi quyền chưa lưu?'],accessGroupDeleteConfirm:['確定刪除此共同組別？仍有成員的組別不能刪除，請先調整帳號指派。','Delete this group? Groups with members cannot be deleted; reassign accounts first.','¿Eliminar el grupo? Primero reasigne sus miembros.','Xóa nhóm này? Phải gán lại thành viên trước.'],accessConflict:['資料已被其他管理員修改。您的編輯保留，請重新載入後再修改。','Another administrator changed this data. Edits remain; reload before editing again.','Otro administrador cambió estos datos. Sus cambios se conservan; recargue.','Quản trị viên khác đã sửa dữ liệu. Giữ nội dung bạn sửa; hãy tải lại.'],accessLimit:['已達 20 組上限。','The 20-group limit has been reached.','Se alcanzó el límite de 20 grupos.','Đã đạt giới hạn 20 nhóm.'],accessInUse:['此組別仍有帳號，請先重新指派成員再刪除。','This group has members. Reassign them before deleting.','Este grupo tiene miembros. Reasígnelos antes de eliminar.','Nhóm còn thành viên. Gán lại trước khi xóa.'],accessInvalid:['未儲存，請填寫組別名稱、選擇至少一個部門，並確認網路。','Not saved. Enter a name, select at least one department and check the connection.','No guardado. Introduzca nombre, seleccione departamentos y revise la conexión.','Chưa lưu. Nhập tên, chọn ít nhất một bộ phận và kiểm tra mạng.'],accessDuplicate:['組別名稱重複，請使用其他名稱。','Group name already exists. Choose another.','El nombre del grupo ya existe.','Tên nhóm đã tồn tại.']
};for(const[k,v]of Object.entries(words))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,n)=>[l,v[n]]));
const ops=['view','create','edit','delete','approve'],opWords={view:'accessView',create:'accessCreate',edit:'accessEdit',delete:'accessDelete',approve:'accessApprove'};
let tab='groups',snapshot=null,draft=null,person=null,dirty=false,busy=false,context='',epoch=0,selectedGroup='',selectedAccount='';
const oldSettings=renderSettings;
renderSettings=async function(){if(view!=='accounts'||profile?.role!=='admin'||!activeCountry)return oldSettings();const ticket=++epoch,key=activeCountry+':'+countryGeneration+':'+profile.account_id;if(context!==key){context=key;snapshot=null;draft=null;person=null;dirty=false;tab='groups';selectedGroup='';selectedAccount='';}$('#content').innerHTML=txt('loading');try{const r=await api({action:'access_admin_get'});if(ticket!==epoch||view!=='accounts'||context!==key)return;snapshot=r;if(person&&!snapshot.accounts.some(a=>a.id===person.id))person=null;if(tab==='people')return drawPeople();drawGroups();}catch{if(ticket===epoch&&view==='accounts')$('#content').innerHTML=`<p role="alert">${txt('error')}</p><button class="btn secondary" id="accessRetry">${txt('refresh')}</button>`;$('#accessRetry')?.addEventListener('click',()=>renderSettings());}};
function tabs(){return `<div class="access-tabs" role="tablist"><button class="btn ${tab==='groups'?'primary':'secondary'}" role="tab" aria-selected="${tab==='groups'}" data-access-tab="groups">${txt('accessGroups')}</button><button class="btn ${tab==='people'?'primary':'secondary'}" role="tab" aria-selected="${tab==='people'}" data-access-tab="people">${txt('accessPeople')}</button></div>`;}
function leave(){return !dirty||confirm(t('accessUnsaved'));}
function bindTabs(){ $$('[data-access-tab]').forEach(b=>b.onclick=()=>{if(busy||!leave())return;dirty=false;draft=null;person=null;tab=b.dataset.accessTab;tab==='groups'?drawGroups():drawPeople();});}
function groupDraft(g){selectedGroup=g?.id||'';draft=g?structuredClone(g):{id:null,name:'',department_ids:[],permissions:{},is_active:true,revision:0};dirty=false;}
function drawGroups(){if(!draft)groupDraft(snapshot.groups.find(g=>g.id===selectedGroup)||snapshot.groups[0]);const g=draft;$('#content').innerHTML=tabs()+`<p class="notice">${txt('accessHelp')}</p><div class="access-layout"><aside class="access-list"><strong>${snapshot.groups.length} / 20 ${txt('accessCount')}</strong><button class="btn primary" id="accessNewGroup" ${snapshot.groups.length>=20?'disabled':''}>${txt('accessNewGroup')}</button>${snapshot.groups.map(x=>`<button class="btn ${x.id===g.id?'primary':'secondary'}" data-access-group="${x.id}">${esc(x.name)}${!x.is_active?' · '+txt('inactive'):''}<small>${snapshot.members.filter(m=>m.group_id===x.id).length} ${txt('accessMembers')}</small></button>`).join('')}</aside><form id="accessGroupForm" class="access-panel"><label>${txt('accessGroupName')}<input id="accessGroupName" class="select" required maxlength="80" value="${esc(g.name)}"></label><label><input id="accessGroupEnabled" type="checkbox" ${g.is_active?'checked':''}>${txt('accessEnabled')}</label><fieldset><legend>${txt('accessDepartments')}</legend><div class="access-checks">${snapshot.departments.map(d=>`<label><input type="checkbox" data-access-dept="${d.id}" ${g.department_ids.includes(d.id)?'checked':''}>${esc(nameOf(d))}</label>`).join('')}</div></fieldset><div class="table-wrap"><table class="matrix access-matrix"><thead><tr><th>${txt('accessForm')}</th>${ops.map(a=>`<th>${txt(opWords[a])}</th>`).join('')}</tr></thead><tbody>${snapshot.resources.map(r=>`<tr><td>${esc(multilingual(r.label))}</td>${ops.map(a=>`<td>${r.actions.includes(a)?`<input aria-label="${esc(multilingual(r.label)+' '+t(opWords[a]))}" type="checkbox" data-access-resource="${r.resource}" data-access-action="${a}" ${g.permissions[r.resource]?.[a]?'checked':''}>`:'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="filter-row"><button class="btn primary" type="submit">${txt('save')}</button><button class="btn secondary" type="button" id="accessReload">${txt('refresh')}</button>${g.id?`<button class="btn danger" type="button" id="accessDeleteGroup">${txt('delete')}</button>`:''}</div><p id="accessMessage" role="status"></p></form></div>`;bindTabs();
 $('#accessNewGroup').onclick=()=>{if(busy||!leave())return;groupDraft();drawGroups();};$$('[data-access-group]').forEach(b=>b.onclick=()=>{if(busy||!leave())return;groupDraft(snapshot.groups.find(x=>x.id===b.dataset.accessGroup));drawGroups();});
 $('#accessGroupName').oninput=e=>{g.name=e.target.value;dirty=true;};$('#accessGroupEnabled').onchange=e=>{g.is_active=e.target.checked;dirty=true;};$$('[data-access-dept]').forEach(el=>el.onchange=()=>{g.department_ids=$$('[data-access-dept]:checked').map(x=>x.dataset.accessDept);dirty=true;});
 $$('[data-access-resource]').forEach(el=>el.onchange=()=>{const r=el.dataset.accessResource,a=el.dataset.accessAction;g.permissions[r]??={};g.permissions[r][a]=el.checked;if(a==='view'&&!el.checked){for(const op of ops)if(op in g.permissions[r])g.permissions[r][op]=false;}else if(el.checked)g.permissions[r].view=true;$$(`[data-access-resource="${r}"]`).forEach(x=>x.checked=!!g.permissions[r][x.dataset.accessAction]);dirty=true;});
 $('#accessGroupForm').onsubmit=e=>{e.preventDefault();if(!g.name.trim()||!g.department_ids.length){$('#accessMessage').textContent=t('accessInvalid');return;}save({action:'access_group_save',id:g.id,revision:g.revision,name:g.name,department_ids:g.department_ids,permissions:g.permissions,is_active:g.is_active});};$('#accessReload').onclick=reload;$('#accessDeleteGroup')?.addEventListener('click',()=>{if(confirm(t('accessGroupDeleteConfirm')))save({action:'access_group_delete',id:g.id,revision:g.revision});});}
async function drawPeople(){const ticket=++epoch;await oldSettings();if(ticket!==epoch||view!=='accounts'||tab!=='people')return;const existing=document.createDocumentFragment();while($('#content').firstChild)existing.append($('#content').firstChild);if(!person&&snapshot.accounts.length)choosePerson(snapshot.accounts.find(a=>a.id===selectedAccount)?.id||snapshot.accounts[0].id);$('#content').innerHTML=tabs()+`<p class="notice">${txt('accessPeopleHelp')}</p><label>${txt('accessAccountChoose')}<select class="select" id="accessAccount">${snapshot.accounts.map(a=>`<option value="${a.id}" ${a.id===person?.id?'selected':''}>${esc(a.account_code+' · '+(a.full_name||''))}</option>`).join('')}</select></label><div id="accessPersonPanel"></div><details class="access-old-accounts"><summary>${txt('accessOldAccounts')}</summary><div id="accessOldAccounts"></div></details>`;$('#accessOldAccounts').append(existing);bindTabs();$('#accessAccount').onchange=e=>{if(busy||!leave()){e.target.value=person?.id||'';return;}choosePerson(e.target.value);personPanel();};personPanel();}
function choosePerson(id){selectedAccount=id;const policy=snapshot.policies.find(p=>p.account_id===id);person={id,managed:policy?.managed||false,revision:policy?.revision||0,groups:snapshot.members.filter(m=>m.account_id===id).map(m=>m.group_id)};dirty=false;}
function personPanel(){if(!person){$('#accessPersonPanel').innerHTML=`<p>${txt('accessNoAccounts')}</p>`;return;}const p=person;$('#accessPersonPanel').innerHTML=`<form id="accessPersonForm" class="access-panel"><label><input id="accessManaged" type="checkbox" ${p.managed?'checked':''}>${txt('accessManaged')}</label><div class="access-checks">${snapshot.groups.map(g=>`<label><input type="checkbox" data-member-group="${g.id}" ${p.groups.includes(g.id)?'checked':''} ${p.managed?'':'disabled'}>${esc(g.name)}${!g.is_active?' · '+txt('inactive'):''}</label>`).join('')||txt('accessEmpty')}</div><p>${p.groups.length} / ${snapshot.groups.length} ${txt('accessCount')}</p><div class="filter-row"><button class="btn primary" type="submit">${txt('save')}</button><button class="btn secondary" type="button" id="accessReload">${txt('refresh')}</button></div><p id="accessMessage" role="status"></p></form>`;
 $('#accessManaged').onchange=e=>{p.managed=e.target.checked;if(!p.managed)p.groups=[];dirty=true;personPanel();};$$('[data-member-group]').forEach(el=>el.onchange=()=>{p.groups=$$('[data-member-group]:checked').map(x=>x.dataset.memberGroup);dirty=true;personPanel();});$('#accessPersonForm').onsubmit=e=>{e.preventDefault();save({action:'access_membership_save',account_id:p.id,revision:p.revision,managed:p.managed,group_ids:p.groups});};$('#accessReload').onclick=reload;}
async function reload(){if(busy||!leave())return;dirty=false;draft=null;person=null;await renderSettings();}
async function save(payload){if(busy)return;busy=true;const key=context;$$('#content input,#content select,#content button').forEach(e=>e.disabled=true);try{const saved=await api(payload);if(payload.action==='access_group_save')selectedGroup=saved.result?.id||payload.id||'';if(payload.action==='access_group_delete')selectedGroup='';if(context!==key||view!=='accounts')return;dirty=false;draft=null;person=null;await renderSettings();$('#accessMessage').textContent=t('saved');}catch(e){const keyName={record_changed:'accessConflict',group_limit:'accessLimit',group_in_use:'accessInUse',duplicate_group:'accessDuplicate'}[e.message]||'accessInvalid';$('#accessMessage')?.replaceChildren(document.createTextNode(t(keyName)));}finally{busy=false;if(context===key&&view==='accounts'){$$('#content input,#content select,#content button').forEach(e=>e.disabled=false);if(tab==='people'&&!person?.managed)$$('[data-member-group]').forEach(e=>e.disabled=true);if(tab==='groups'&&snapshot.groups.length>=20)$('#accessNewGroup').disabled=true;}}}
const oldResetCountry=resetCountry;resetCountry=function(){if(busy||!leave())return;dirty=false;draft=null;person=null;oldResetCountry();};
const oldLogout=logout;logout=function(){if(busy||!leave())return;dirty=false;draft=null;person=null;oldLogout();};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
const beforeRender=render;render=function(){beforeRender();if(view==='accounts')$$('.side [data-view]').forEach(b=>{const action=b.onclick;b.onclick=e=>{if(busy||!leave())return;dirty=false;action?.call(b,e);};});};
})();
